def count_nums(arr):
    def digit_sum(num):
        sign = -1 if num < 0 else 1
        num = abs(num)
        total = 0
        while num > 0:
            total += num % 10
            num //= 10
        return total * sign

    return sum(1 for num in arr if digit_sum(num) > 0)
